def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record."""
    role_id = user.get("ROLE_ID", "")
    matching_scope = None

    # Preserve role-file order; the first matching permission row applies.
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_scope = row.get("scope", "")
            break

    # A missing permission row is deny-by-default.
    if matching_scope is None:
        return False

    # DELETE is subject to the soft-deletable row-level rule.
    if action == "DELETE" and record.get("DEL_FLG", "") == "Y":
        return False

    if role_id == "ADMIN":
        return True

    if matching_scope == "NONE":
        return False
    if matching_scope == "ALL":
        return True
    if matching_scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if matching_scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    return False
